old:
if mutation.success && !mutation.diff.is_empty() {
    if let Err(error) = persist_ui(loaded) {
        let document = UiDocument::from_json_str(&before).map_err(|reload| HeadlessMcpCallFailure::new("mcp.headless_reload_failed", reload.to_string()))?;
        loaded.session = UiAuthoringSession::new(document);
        return Err(error);
    }
}

new:
if mutation.success
    && !mutation.diff.is_empty()
    && let Err(error) = persist_ui(loaded)
{
    let document = UiDocument::from_json_str(&before).map_err(|reload| HeadlessMcpCallFailure::new("mcp.headless_reload_failed", reload.to_string()))?;
    loaded.session = UiAuthoringSession::new(document);
    return Err(error);
}
